CREATE OR REPLACE FUNCTION public.add_member_to_group(p_conversation_id uuid, p_invitee_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
  v_host uuid;
begin
  if v_me is null then raise exception 'No autenticado'; end if;

  select gc.created_by into v_host
  from public.group_conversations gc
  where gc.id=p_conversation_id;

  if v_host is null or v_host<>v_me then
    raise exception 'Solo el administrador puede invitar participantes';
  end if;

  if exists(
    select 1 from public.group_conversation_members gm
    where gm.conversation_id=p_conversation_id and gm.user_id=p_invitee_id
  ) then
    return;
  end if;

  if not exists(
    select 1 from public.contacts c
    where c.owner_id=v_me and c.contact_id=p_invitee_id
  ) then
    raise exception 'Solo puedes invitar personas de tu lista de contactos';
  end if;

  insert into public.group_conversation_members(conversation_id,user_id,invited_by)
  values(p_conversation_id,p_invitee_id,v_me);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_group_from_direct(p_peer_id uuid, p_invitee_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
  v_host uuid;
  v_room uuid;
begin
  if v_me is null then raise exception 'No autenticado'; end if;
  if p_peer_id is null or p_invitee_id is null or p_peer_id in (v_me,p_invitee_id) or p_invitee_id=v_me then
    raise exception 'Participantes inválidos';
  end if;
  if not exists(
    select 1 from public.contacts c
    where c.owner_id=v_me and c.contact_id=p_peer_id
  ) then
    raise exception 'La conversación debe ser con un contacto';
  end if;

  v_host:=public.direct_conversation_host(p_peer_id);
  if v_host<>v_me then
    raise exception 'Solo el administrador puede invitar participantes';
  end if;

  if not exists(
    select 1 from public.contacts c
    where c.owner_id=v_me and c.contact_id=p_invitee_id
  ) then
    raise exception 'Solo puedes invitar personas de tu lista de contactos';
  end if;

  insert into public.group_conversations(created_by,title)
  values(v_host,'') returning id into v_room;

  insert into public.group_conversation_members(conversation_id,user_id,invited_by) values
    (v_room,v_host,v_host),
    (v_room,p_peer_id,v_host),
    (v_room,p_invitee_id,v_host);

  return v_room;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_group_from_direct(p_peer_id uuid, p_invitee_id uuid, p_title text DEFAULT ''::text)
 RETURNS TABLE(conversation_id uuid, created boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
  v_group uuid;
  v_signature text;
  v_title text:=left(trim(coalesce(p_title,'')),60);
begin
  if v_me is null then raise exception 'No autenticado'; end if;
  if p_peer_id in (v_me,p_invitee_id) or p_invitee_id=v_me then
    raise exception 'Participantes inválidos';
  end if;
  if not exists(
    select 1 from public.contacts c
    where c.owner_id=v_me and c.contact_id=p_peer_id
  ) then
    raise exception 'La conversación debe ser con un contacto';
  end if;
  if not exists(
    select 1 from public.contacts c
    where c.owner_id in (v_me,p_peer_id) and c.contact_id=p_invitee_id
  ) then
    raise exception 'Solo puedes invitar contactos de alguno de los participantes';
  end if;

  select md5(string_agg(x::text, ',' order by x::text))
    into v_signature
  from unnest(array[v_me,p_peer_id,p_invitee_id]) as x;

  select g.id into v_group
  from public.group_conversations g
  where g.member_signature=v_signature
  limit 1;

  if v_group is not null then
    return query select v_group,false;
    return;
  end if;

  insert into public.group_conversations(created_by,title,member_signature)
  values(v_me,v_title,v_signature)
  returning id into v_group;

  insert into public.group_conversation_members(conversation_id,user_id,invited_by)
  values
    (v_group,v_me,v_me),
    (v_group,p_peer_id,v_me),
    (v_group,p_invitee_id,v_me);

  return query select v_group,true;
exception
  when unique_violation then
    select g.id into v_group
    from public.group_conversations g
    where g.member_signature=v_signature
    limit 1;
    if v_group is not null then
      return query select v_group,false;
      return;
    end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.direct_conversation_host(p_peer_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
  v_host uuid;
begin
  if v_me is null then raise exception 'No autenticado'; end if;
  if p_peer_id is null or p_peer_id=v_me then raise exception 'Participante inválido'; end if;

  select m.sender_id into v_host
  from public.messages m
  where (m.sender_id=v_me and m.recipient_id=p_peer_id)
     or (m.sender_id=p_peer_id and m.recipient_id=v_me)
  order by m.created_at asc, m.id asc
  limit 1;

  return coalesce(v_host,v_me);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_online_video_invite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  recipient_status text;
  recipient_seen timestamptz;
begin
  if new.signal_type <> 'invite' then
    return new;
  end if;

  select p.status, p.last_seen_at
    into recipient_status, recipient_seen
  from public.profiles p
  where p.id = new.recipient_id;

  if recipient_status is null
     or recipient_status = 'offline'
     or recipient_seen is null
     or recipient_seen < now() - interval '15 seconds' then
    raise exception 'RECIPIENT_OFFLINE';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_direct_invite_candidates(p_peer_id uuid)
 RETURNS TABLE(id uuid, email text, display_name text, personal_message text, display_picture text, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
  v_host uuid;
begin
  if v_me is null then raise exception 'No autenticado'; end if;
  if p_peer_id is null or p_peer_id=v_me then raise exception 'Participante inválido'; end if;
  if not exists(
    select 1 from public.contacts c
    where c.owner_id=v_me and c.contact_id=p_peer_id
  ) then
    raise exception 'La conversación debe ser con un contacto';
  end if;

  v_host:=public.direct_conversation_host(p_peer_id);
  if v_host<>v_me then
    raise exception 'Solo el administrador puede invitar participantes';
  end if;

  return query
  select p.id,p.email,p.display_name,p.personal_message,p.display_picture,p.status
  from public.contacts c
  join public.profiles p on p.id=c.contact_id
  where c.owner_id=v_me
    and p.id<>p_peer_id
    and p.id<>v_me
  order by p.display_name,p.email;
end;
$function$

CREATE OR REPLACE FUNCTION public.heartbeat_presence()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  touched_at timestamptz := now();
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  update public.profiles
  set last_seen_at = touched_at,
      updated_at = now()
  where id = auth.uid();

  return touched_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.limit_video_invite_lifetime()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.signal_type='invite' then
    new.expires_at := least(new.expires_at, now() + interval '45 seconds');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_conversation_participant(p_conversation_id uuid, p_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
  v_host uuid;
begin
  if v_me is null then raise exception 'No autenticado'; end if;
  select created_by into v_host from public.group_conversations where id=p_conversation_id;
  if v_host is null or v_host<>v_me then
    raise exception 'Solo el administrador puede eliminar participantes';
  end if;
  if p_member_id=v_host then
    raise exception 'El administrador no puede eliminarse de la conversación';
  end if;

  delete from public.group_conversation_members
  where conversation_id=p_conversation_id and user_id=p_member_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.remove_friend(p_contact_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
begin
  if v_me is null then raise exception 'No autenticado'; end if;
  if p_contact_id is null or p_contact_id=v_me then raise exception 'Contacto inválido'; end if;

  delete from public.contacts
  where (owner_id=v_me and contact_id=p_contact_id)
     or (owner_id=p_contact_id and contact_id=v_me);

  delete from public.friend_requests
  where (sender_id=v_me and receiver_id=p_contact_id)
     or (sender_id=p_contact_id and receiver_id=v_me);
end;
$function$

CREATE OR REPLACE FUNCTION public.rename_group(p_conversation_id uuid, p_title text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me uuid:=auth.uid();
begin
  if v_me is null then raise exception 'No autenticado'; end if;
  if not exists(
    select 1 from public.group_conversations g
    where g.id=p_conversation_id and g.created_by=v_me
  ) then
    raise exception 'Solo quien creó el grupo puede cambiar el nombre';
  end if;

  update public.group_conversations
  set title=left(trim(coalesce(p_title,'')),60)
  where id=p_conversation_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_friend_request(p_request uuid, p_accept boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.friend_requests;
begin
  select * into r from public.friend_requests where id=p_request and receiver_id=auth.uid() and status='pending' for update;
  if not found then raise exception 'Solicitud no disponible'; end if;
  update public.friend_requests set status=case when p_accept then 'accepted' else 'rejected' end, responded_at=now() where id=p_request;
  if p_accept then
    insert into public.contacts(owner_id,contact_id) values(r.sender_id,r.receiver_id) on conflict do nothing;
    insert into public.contacts(owner_id,contact_id) values(r.receiver_id,r.sender_id) on conflict do nothing;
  end if;
end$function$

CREATE OR REPLACE FUNCTION public.respond_friend_request(p_request_id uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.friend_requests%rowtype;
begin
  select * into r from public.friend_requests where id=p_request_id for update;
  if not found then raise exception 'Solicitud no encontrada'; end if;
  if r.receiver_id <> auth.uid() then raise exception 'No autorizado'; end if;
  if r.status <> 'pending' then raise exception 'La solicitud ya fue procesada'; end if;
  if p_action='accept' then
    update public.friend_requests set status='accepted',responded_at=now() where id=p_request_id;
    insert into public.contacts(owner_id,contact_id) values(r.sender_id,r.receiver_id) on conflict do nothing;
    insert into public.contacts(owner_id,contact_id) values(r.receiver_id,r.sender_id) on conflict do nothing;
  elsif p_action='decline' then
    update public.friend_requests set status='declined',responded_at=now() where id=p_request_id;
  else
    raise exception 'Acción inválida';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.send_friend_request(p_receiver_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'No autenticado'; end if;
  if p_receiver_id=auth.uid() then raise exception 'No puedes enviarte una solicitud a ti mismo'; end if;
  if not exists(select 1 from public.profiles where id=p_receiver_id) then raise exception 'Usuario no encontrado'; end if;
  if exists(select 1 from public.contacts where owner_id=auth.uid() and contact_id=p_receiver_id) then raise exception 'El usuario ya está en tus contactos'; end if;
  if exists(select 1 from public.blocks b where (b.owner_id=auth.uid() and b.blocked_id=p_receiver_id) or (b.owner_id=p_receiver_id and b.blocked_id=auth.uid())) then raise exception 'No se puede enviar la solicitud'; end if;
  insert into public.friend_requests(sender_id,receiver_id) values(auth.uid(),p_receiver_id) returning id into v_id;
  return v_id;
end;
$function$
